CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, username TEXT UNIQUE NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','supervisor','staff')), team_group TEXT NOT NULL DEFAULT 'A', password_salt TEXT NOT NULL, password_hash TEXT NOT NULL, security_question TEXT NOT NULL, security_answer_salt TEXT NOT NULL, security_answer_hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL, expires_at TEXT NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY, order_no TEXT NOT NULL, operator_id TEXT NOT NULL, team_group TEXT NOT NULL DEFAULT 'A', stage TEXT NOT NULL, payload_json TEXT NOT NULL, calculation_json TEXT NOT NULL, created_at TEXT NOT NULL, deleted_at TEXT, FOREIGN KEY(operator_id) REFERENCES users(id));
CREATE INDEX IF NOT EXISTS idx_orders_operator ON orders(operator_id, created_at DESC);
